<?php require 'header.php'; $db=db_load(); $events=[]; foreach($db['appointments'] as $a){$p=find_item($db['patients'],$a['patient_id']);$events[]=['id'=>$a['id'],'title'=>$a['time'].' - '.($p['name']??'Patient'),'start'=>$a['date'].'T'.$a['time'],'url'=>'appointment-edit.php?id='.$a['id']];} $json=[]; foreach($db['appointments'] as $a){$p=find_item($db['patients'],$a['patient_id']);$json[]=['id'=>$a['id'],'title'=>$a['time'].' - '.($p['name']??'Patient'),'start'=>$a['date'].'T'.$a['time'],'extendedProps'=>['appointment'=>$a['number']]];} ?><div class="admin-top"><h1>Appointment Calendar</h1></div><div class="calendar" id="calendar"></div><script>document.addEventListener('DOMContentLoaded',()=>{const c=document.getElementById('calendar');const cal=new FullCalendar.Calendar(c,{initialView:'dayGridMonth',headerToolbar:{left:'prev,next today',center:'title',right:'dayGridMonth,timeGridWeek,timeGridDay'},height:'auto',events:<?=json_encode($json)?>,eventClick:function(info){info.jsEvent.preventDefault();window.location='appointment-edit.php?id='+encodeURIComponent(info.event.id)}});cal.render();});</script><?php require 'footer.php'; ?>
